#!/usr/bin/env python3
"""Build final 5-seed summary tables from registry.yaml.

Reads all pi05 eval experiments for seeds 42-46, applies data integration
overrides per ROADMAP notes, computes mean ± sample std for each method × k.
"""

import yaml
import math
import sys
import re

REGISTRY_PATH = "/home/ubuntu/.agent-ml-research-be-idea-gen-0515-2/projects/importance_margin_vla_compress/registry.yaml"

SEEDS = [42, 43, 44, 45, 46]
METHODS = ["l2norm", "random", "attn"]
K_VALUES = [0.95, 0.9, 0.85, 0.75, 0.7, 0.5]

# Data integration overrides (ROADMAP notes)
OVERRIDES = {
    ("attn", 0.75, 43): 52.0,    # use cqa1 value
    ("random", 0.9, 43): 35.0,   # use v2 value (D292)
}

def extract_sr(exp):
    """Extract success rate from an experiment entry, handling all format variants."""
    if not isinstance(exp, dict):
        return None

    metrics = exp.get("metrics")
    if metrics is None:
        return None

    # metrics might be a string (edge case)
    if isinstance(metrics, (int, float)):
        return float(metrics)
    if isinstance(metrics, str):
        try:
            return float(metrics)
        except (ValueError, TypeError):
            return None
    if not isinstance(metrics, dict):
        return None

    # Try various key names
    for key in ["success_rate", "SR", "overall_sr", "sr"]:
        val = metrics.get(key)
        if val is not None:
            try:
                v = float(val)
                # Convert ratio to percentage if needed (values < 1 are likely ratios)
                if v <= 1.0 and v > 0:
                    v = v * 100.0
                return v
            except (ValueError, TypeError):
                continue

    return None

def extract_seed(exp_id):
    """Extract seed number from experiment ID."""
    m = re.search(r'seed(\d+)', exp_id)
    return int(m.group(1)) if m else None

def extract_method(exp_id):
    """Extract method from experiment ID."""
    if '_l2norm_' in exp_id:
        return 'l2norm'
    elif '_random_' in exp_id:
        return 'random'
    elif '_attn_' in exp_id or '_attention_' in exp_id:
        return 'attn'
    return None

def extract_k(exp_id):
    """Extract keep ratio from experiment ID."""
    m = re.search(r'_k0?(\d+)_', exp_id)
    if m:
        digits = m.group(1)
        if digits.startswith('0'):
            return float('0.' + digits)
        k_map = {'95': 0.95, '9': 0.9, '85': 0.85, '75': 0.75, '7': 0.7, '5': 0.5,
                  '05': 0.05, '50': 0.5, '70': 0.7}
        return k_map.get(digits)
    return None

def sample_std(values):
    """Compute sample standard deviation (n-1)."""
    n = len(values)
    if n < 2:
        return 0.0
    mean = sum(values) / n
    variance = sum((x - mean) ** 2 for x in values) / (n - 1)
    return math.sqrt(variance)

def main():
    with open(REGISTRY_PATH, 'r') as f:
        registry = yaml.safe_load(f)

    experiments = registry.get("experiments", {})

    # Collect SR values: data[method][k] = {seed: sr_value}
    data = {m: {k: {} for k in K_VALUES} for m in METHODS}

    for exp_id, exp in experiments.items():
        if not isinstance(exp, dict):
            continue

        # Only pi05 eval experiments on libero_long (libero_10 suite)
        if not exp_id.startswith("eval_pi05_"):
            continue

        # Must be DONE with success conclusion
        status = exp.get("status")
        conclusion = exp.get("conclusion")
        if status != "DONE" or conclusion != "success":
            continue

        seed = extract_seed(exp_id)
        method = extract_method(exp_id)
        k = extract_k(exp_id)

        if seed not in SEEDS or method not in METHODS or k not in K_VALUES:
            continue

        sr = extract_sr(exp)
        if sr is None:
            continue

        # Apply overrides
        override_key = (method, k, seed)
        if override_key in OVERRIDES:
            sr = OVERRIDES[override_key]

        # If multiple experiments for same (method, k, seed), keep the latest
        # (registry is sorted by updated_at desc, first encountered = latest)
        if seed not in data[method][k]:
            data[method][k][seed] = sr

    # Print Importance Margin Profile table (L2norm vs Random)
    print("=" * 80)
    print("IMPORTANCE MARGIN PROFILE (5-seed, sample std)")
    print("=" * 80)
    print(f"| k    | L2norm mean±std | seeds | Random mean±std | seeds | Margin |")
    print(f"|------|-----------------|-------|-----------------|-------|--------|")

    for k in K_VALUES:
        l2_vals = [data["l2norm"][k][s] for s in SEEDS if s in data["l2norm"][k]]
        rnd_vals = [data["random"][k][s] for s in SEEDS if s in data["random"][k]]

        l2_str = f"{sum(l2_vals)/len(l2_vals):.1f}%±{sample_std(l2_vals):.1f}" if l2_vals else "N/A"
        l2_n = f"{len(l2_vals)}/5"
        rnd_str = f"{sum(rnd_vals)/len(rnd_vals):.1f}%±{sample_std(rnd_vals):.1f}" if rnd_vals else "N/A"
        rnd_n = f"{len(rnd_vals)}/5"

        if l2_vals and rnd_vals:
            margin = sum(l2_vals)/len(l2_vals) - sum(rnd_vals)/len(rnd_vals)
            margin_str = f"{margin:+.1f}pp"
        else:
            margin_str = "N/A"

        print(f"| {k:<4} | {l2_str:<15} | {l2_n:<5} | {rnd_str:<15} | {rnd_n:<5} | {margin_str:<6} |")

    # Print per-seed detail for L2norm and Random
    print()
    print("L2norm per-seed:")
    for k in K_VALUES:
        seeds_str = ", ".join(f"s{s}={data['l2norm'][k].get(s, '?')}" for s in SEEDS)
        print(f"  k={k}: {seeds_str}")

    print()
    print("Random per-seed:")
    for k in K_VALUES:
        seeds_str = ", ".join(f"s{s}={data['random'][k].get(s, '?')}" for s in SEEDS)
        print(f"  k={k}: {seeds_str}")

    # Print Attn Cliff+Plateau table
    print()
    print("=" * 80)
    print("ATTN CLIFF+PLATEAU (5-seed, sample std)")
    print("=" * 80)
    print(f"| k    | Attn mean±std   | seeds | Zone           |")
    print(f"|------|-----------------|-------|----------------|")

    zone_map = {0.95: "cliff top", 0.9: "cliff", 0.85: "cliff→plateau",
                0.75: "plateau", 0.7: "plateau", 0.5: "plateau"}

    for k in K_VALUES:
        attn_vals = [data["attn"][k][s] for s in SEEDS if s in data["attn"][k]]
        attn_str = f"{sum(attn_vals)/len(attn_vals):.1f}%±{sample_std(attn_vals):.1f}" if attn_vals else "N/A"
        attn_n = f"{len(attn_vals)}/5"
        zone = zone_map.get(k, "")
        print(f"| {k:<4} | {attn_str:<15} | {attn_n:<5} | {zone:<14} |")

    print()
    print("Attn per-seed:")
    for k in K_VALUES:
        seeds_str = ", ".join(f"s{s}={data['attn'][k].get(s, '?')}" for s in SEEDS)
        print(f"  k={k}: {seeds_str}")

    # Summary of missing data
    print()
    print("=" * 80)
    print("MISSING DATA SUMMARY")
    print("=" * 80)
    for method in METHODS:
        for k in K_VALUES:
            missing = [s for s in SEEDS if s not in data[method][k]]
            if missing:
                print(f"  {method} k={k}: missing seeds {missing}")

if __name__ == "__main__":
    main()

